router16.post("/:id/analyze", zValidator("json", external_exports.object({ template_id: external_exports.enum(["objections", "quality", "upsell", "competitors", "commitments"]) })), async (c2) => {
  const call = await getCall(c2.get("workspaceId"), c2.req.param("id"));
  if (!call) return c2.json({ error: "Call not found" }, 404);
  const normalized = normalizeCall(call);
  const transcript = normalized.transcript.map((line) => {
    const entry = line;
    return `${entry.speaker ?? "Speaker"}: ${entry.text ?? ""}`;
  }).join("\n");
  const templateId = c2.req.valid("json").template_id;
  const prompts = {
    objections: "Extract every objection raised. Group duplicates and include concise supporting context.",
    quality: "Score this discovery call from 1 to 10 and explain the score using discovery depth, listening, qualification, and agreed next steps.",
    upsell: "Identify credible upsell or cross-sell opportunities. Explain the evidence and recommended follow-up.",
    competitors: "Summarize every competitor mention, the buyer's sentiment, and any product comparison.",
    commitments: "List every commitment made, who owns it, and any stated deadline."
  };
  let output = "";
  if (transcript) {
    const result = await aiGateway({
      prompt: `${prompts[templateId]}

Transcript:
${transcript}`,
      maxTokens: 900
    }).catch(() => null);
    if (result) output = result.text;
  }
  if (!output) {
    const summary = normalized.ai_summary || normalized.overview || "No AI summary is available.";
    output = `${prompts[templateId]}

Current call evidence:
${summary}

${transcript ? `Transcript reviewed: ${normalized.transcript.length} segments.` : "A transcript is not available, so this result is limited to stored call insights."}`;
  }
  const encoder = new TextEncoder();
  const words = output.split(/(\s+)/);
  const stream2 = new ReadableStream({
    async start(controller) {
      for (let index = 0; index < words.length; index += 8) {
        controller.enqueue(encoder.encode(words.slice(index, index + 8).join("")));
        await new Promise((resolve2) => setTimeout(resolve2, 15));
      }
      controller.close();
    }
  });
  return new Response(stream2, { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-cache" } });
});

