router32.get("/", async (c2) => {
  const status = c2.req.query("status");
  const search = c2.req.query("search") ?? "";
  const linkedRecordId = c2.req.query("linked_record_id");
  const appliedToInvoice = c2.req.query("applied_to_invoice");
  let q2 = supabase.from("nodes").select("id,data,created_at,updated_at,created_by").eq("workspace_id", c2.get("workspaceId")).eq("object_type", "credit_note").order("created_at", { ascending: false });
  if (status) q2 = q2.eq("data->>status", status);
  if (linkedRecordId) q2 = q2.eq("data->>linked_record_id", linkedRecordId);
  if (appliedToInvoice) {
    const { data: edges } = await supabase.from("edges").select("from_node_id").eq("workspace_id", c2.get("workspaceId")).eq("to_node_id", appliedToInvoice).eq("relationship", "APPLIED_TO");
    const ids = (edges ?? []).map((e2) => e2.from_node_id);
    if (ids.length === 0) return c2.json([]);
    q2 = q2.in("id", ids);
  }
  const { data, error } = await q2;
  if (error) return c2.json({ error: error.message }, 500);
  const result = (data ?? []).filter((row) => {
    if (!search) return true;
    const d2 = row.data;
    return String(d2.client_name ?? "").toLowerCase().includes(search.toLowerCase()) || String(d2.credit_reason ?? "").toLowerCase().includes(search.toLowerCase());
  }).map((row) => ({ id: row.id, ...row.data, created_at: row.created_at, updated_at: row.updated_at, created_by: row.created_by }));
  if (result.length) {
    const ids = result.map((r2) => r2.id);
    const { data: edges } = await supabase.from("edges").select("from_node_id,to_node_id,relationship").in("from_node_id", ids).in("relationship", ["APPLIED_TO", "ASSIGNED_REVIEWER"]);
    const edgeMap = {};
    for (const e2 of edges ?? []) {
      edgeMap[e2.from_node_id] ??= {};
      edgeMap[e2.from_node_id][e2.relationship] = e2.to_node_id;
    }
    return c2.json(result.map((r2) => ({ ...r2, edges: edgeMap[r2.id] ?? {} })));
  }
  return c2.json(result);
});
