app.get("/api/cron/daily", async (c2) => {
  const secret3 = process.env.CRON_SECRET;
  if (!secret3) {
    return c2.json({ error: "Cron disabled \u2014 CRON_SECRET is not configured." }, 503);
  }
  const provided = c2.req.header("Authorization") ?? `Bearer ${c2.req.query("secret") ?? ""}`;
  if (provided !== `Bearer ${secret3}`) {
    return c2.json({ error: "Unauthorized" }, 401);
  }
  const only = c2.req.query("only");
  if (only === "lead_scoring") {
    const r2 = await runLeadScoring();
    return c2.json({ ran: true, only, at: (/* @__PURE__ */ new Date()).toISOString(), result: r2 });
  }
  if (only === "deal_alerts") {
    const r2 = await runDealAlerts();
    return c2.json({ ran: true, only, at: (/* @__PURE__ */ new Date()).toISOString(), result: r2 });
  }
  if (only === "workflows") {
    const r2 = await runAllWorkflows().catch((e2) => ({ error: String(e2) }));
    return c2.json({ ran: true, only, at: (/* @__PURE__ */ new Date()).toISOString(), result: r2 });
  }
  const results = await runAllDaily();
  const workflows = await runAllWorkflows().catch((e2) => ({ error: String(e2) }));
  const vertical = await runAllVertical().catch((e2) => ({ error: String(e2) }));
  return c2.json({ ran: true, at: (/* @__PURE__ */ new Date()).toISOString(), results, workflows, vertical });
});
